import java.io.*;
import java.util.*;

public class Variant2 {
    public static void main(String[] args) {
        new Variant2().run();
    }

    private void run() {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
             PrintWriter pw = new PrintWriter(System.out)) {
            int n = Integer.parseInt(br.readLine());
            char[] s = br.readLine().toCharArray();
            int[] ugliness = new int[n];
            for (int i = 0; i < n; i++) {
                ugliness[i] = -Integer.parseInt(br.readLine());
            }

            Graph graph = new Graph(1 + 26 + n / 2 + 1);
            for (char c = 'a'; c <= 'z'; c++) {
                for (int i = 0; i < n / 2; i++) {
                    int cost = 0;
                    if (c == s[i]) cost = Math.min(cost, ugliness[i]);
                    if (c == s[n - 1 - i]) cost = Math.min(cost, ugliness[n - 1 - i]);
                    graph.addFlowWeightedEdge(1 + (c - 'a'), 1 + 26 + i, cost, 1);
                }
            }

            int[] occurs = new int[128];
            for (char ch : s) occurs[ch]++;
            for (char c = 'a'; c <= 'z'; c++) {
                graph.addFlowWeightedEdge(0, 1 + (c - 'a'), 0, occurs[c]);
            }

            for (int i = 0; i < n / 2; i++) {
                graph.addFlowWeightedEdge(1 + 26 + i, 1 + 26 + n / 2, 0, 2);
            }

            Pair<Long, Long> flow = MinCostFlow.minCostMaxFlow(graph, 0, 1 + 26 + n / 2, true, n);
            pw.println(-flow.first);
            pw.close();
        } catch (IOException e) {
            throw new RuntimeException(e);
        }
    }

    static class Graph {
        protected int vertexCount, edgeCount;
        private int[] firstOutbound, from, to, nextOutbound;
        private long[] weight, capacity;

        public Graph(int vertexCount) {
            this(vertexCount, vertexCount);
        }

        public Graph(int vertexCount, int edgeCapacity) {
            this.vertexCount = vertexCount;
            firstOutbound = new int[vertexCount];
            Arrays.fill(firstOutbound, -1);
            from = new int[edgeCapacity];
            to = new int[edgeCapacity];
            nextOutbound = new int[edgeCapacity];
        }

        public int addEdge(int u, int v, long w, long cap, int rev) {
            ensureCapacity(edgeCount + 1);
            nextOutbound[edgeCount] = firstOutbound[u];
            firstOutbound[u] = edgeCount;
            from[edgeCount] = u;
            to[edgeCount] = v;
            if (cap != 0) {
                if (capacity == null) capacity = new long[from.length];
                capacity[edgeCount] = cap;
            }
            if (w != 0) {
                if (weight == null) weight = new long[from.length];
                weight[edgeCount] = w;
            }
            return edgeCount++;
        }

        public int addFlowWeightedEdge(int u, int v, long w, long cap) {
            if (cap == 0) return addEdge(u, v, w, 0, -1);
            int last = edgeCount;
            addEdge(v, u, -w, 0, -1);
            return addEdge(u, v, w, cap, -1);
        }

        protected void ensureCapacity(int size) {
            if (from.length < size) {
                int newSize = Math.max(size, 2 * from.length);
                from = Arrays.copyOf(from, newSize);
                to = Arrays.copyOf(to, newSize);
                nextOutbound = Arrays.copyOf(nextOutbound, newSize);
                if (weight != null) weight = Arrays.copyOf(weight, newSize);
                if (capacity != null) capacity = Arrays.copyOf(capacity, newSize);
            }
        }

        public int firstOutbound(int v) { return firstOutbound[v]; }
        public int nextOutbound(int id) { return nextOutbound[id]; }
        public int source(int id) { return from[id]; }
        public int destination(int id) { return to[id]; }
        public long weight(int id) { return weight != null ? weight[id] : 0; }
        public long capacity(int id) { return capacity != null ? capacity[id] : 0; }

        public void pushFlow(int id, long f) {
            if (f == 0) return;
            capacity[id] -= f;
            capacity[id ^ 1] += f;
        }

        public boolean isSparse() { return vertexCount == 0 || edgeCount * 20 / vertexCount <= vertexCount; }
    }

    static class MinCostFlow {
        private final Graph g;
        private final int src, dst;
        private final long[] phi;
        private final long[] dist;
        private final int[] prev;
        private final int n;
        private final int[] visited;
        private int visitIdx;

        public MinCostFlow(Graph g, int src, int dst, boolean hasNeg) {
            this.g = g;
            this.src = src;
            this.dst = dst;
            n = g.vertexCount;
            phi = new long[n];
            dist = new long[n];
            prev = new int[n];
            if (hasNeg) fordBellman();
            if (g.isSparse()) {
                visited = null;
            } else {
                visited = new int[n];
            }
        }

        private void fordBellman() {
            Arrays.fill(phi, Long.MAX_VALUE);
            phi[src] = 0;
            boolean[] inQ = new boolean[n];
            int[] q = new int[n + 1];
            int head = 0, tail = 0;
            q[tail++] = src;
            inQ[src] = true;
            int steps = 0, maxSteps = 2 * n * n;
            while (head != tail) {
                int u = q[head++];
                if (head == n) head = 0;
                inQ[u] = false;
                for (int e = g.firstOutbound(u); e != -1; e = g.nextOutbound(e)) {
                    if (g.capacity(e) == 0) continue;
                    int v = g.destination(e);
                    long nd = phi[u] + g.weight(e);
                    if (phi[v] > nd) {
                        phi[v] = nd;
                        if (!inQ[v]) {
                            q[tail++] = v;
                            inQ[v] = true;
                            if (tail == n) tail = 0;
                        }
                    }
                }
                if (++steps > maxSteps) throw new IllegalArgumentException("Negative cycle");
            }
        }

        public static Pair<Long, Long> minCostMaxFlow(Graph g, int s, int d, boolean hasNeg, long maxF) {
            return new MinCostFlow(g, s, d, hasNeg).run(maxF);
        }

        private Pair<Long, Long> run(long maxF) {
            long cost = 0, flow = 0;
            while (maxF > 0) {
                dijkstra();
                if (prev[dst] == -1) break;
                for (int i = 0; i < n; i++) {
                    if (dist[i] != Long.MAX_VALUE) phi[i] += dist[i];
                }
                long f = maxF;
                for (int v = dst; v != src; v = g.source(prev[v])) {
                    f = Math.min(f, g.capacity(prev[v]));
                }
                maxF -= f;
                long c = 0;
                for (int v = dst; v != src; v = g.source(prev[v])) {
                    c += g.weight(prev[v]);
                }
                cost += c * f;
                flow += f;
                for (int v = dst; v != src; v = g.source(prev[v])) {
                    g.pushFlow(prev[v], f);
                }
            }
            return new Pair<>(cost, flow);
        }

        private void dijkstra() {
            Arrays.fill(dist, Long.MAX_VALUE);
            Arrays.fill(prev, -1);
            dist[src] = 0;
            if (visited == null) {
                Heap heap = new Heap(n, (a, b) -> Long.compare(dist[a], dist[b]), n);
                heap.add(src);
                while (!heap.isEmpty()) {
                    int u = heap.poll();
                    for (int e = g.firstOutbound(u); e != -1; e = g.nextOutbound(e)) {
                        if (g.capacity(e) == 0) continue;
                        int v = g.destination(e);
                        long nd = dist[u] + g.weight(e) - phi[v] + phi[u];
                        if (dist[v] > nd) {
                            dist[v] = nd;
                            if (heap.getIndex(v) == -1) heap.add(v);
                            else heap.shiftUp(heap.getIndex(v));
                            prev[v] = e;
                        }
                    }
                }
            } else {
                for (int iter = 0; iter < n; iter++) {
                    int u = -1;
                    long minD = Long.MAX_VALUE;
                    for (int i = 0; i < n; i++) {
                        if (visited[i] != visitIdx && dist[i] < minD) {
                            minD = dist[i];
                            u = i;
                        }
                    }
                    if (u == -1) break;
                    visited[u] = visitIdx;
                    for (int e = g.firstOutbound(u); e != -1; e = g.nextOutbound(e)) {
                        if (g.capacity(e) == 0) continue;
                        int v = g.destination(e);
                        if (visited[v] != visitIdx) {
                            long nd = dist[u] + g.weight(e) - phi[v] + phi[u];
                            if (dist[v] > nd) {
                                dist[v] = nd;
                                prev[v] = e;
                            }
                        }
                    }
                }
                visitIdx++;
            }
        }
    }

    static class Heap {
        private int[] heap;
        private int[] pos;
        private int size;
        private IntComparator cmp;

        public Heap(int maxVal, IntComparator cmp, int cap) {
            this.cmp = cmp;
            heap = new int[cap];
            pos = new int[maxVal];
            Arrays.fill(pos, -1);
        }

        public boolean isEmpty() { return size == 0; }

        public void add(int x) {
            heap[size] = x;
            pos[x] = size;
            shiftUp(size++);
        }

        public void shiftUp(int i) {
            while (i > 0) {
                int p = (i - 1) >>> 1;
                if (cmp.compare(heap[p], heap[i]) <= 0) break;
                swap(i, p);
                i = p;
            }
        }

        public int poll() {
            int x = heap[0];
            pos[x] = -1;
            if (--size > 0) {
                heap[0] = heap[size];
                pos[heap[0]] = 0;
                shiftDown(0);
            }
            return x;
        }

        private void shiftDown(int i) {
            while (true) {
                int l = (i << 1) + 1;
                if (l >= size) break;
                if (l + 1 < size && cmp.compare(heap[l], heap[l + 1]) > 0) l++;
                if (cmp.compare(heap[i], heap[l]) <= 0) break;
                swap(i, l);
                i = l;
            }
        }

        private void swap(int i, int j) {
            int t = heap[i]; heap[i] = heap[j]; heap[j] = t;
            pos[heap[i]] = i; pos[heap[j]] = j;
        }

        public int getIndex(int x) { return pos[x]; }
    }

    static class Pair<U, V> {
        public final U first;
        public final V second;
        public Pair(U f, V s) { first = f; second = s; }
        public static <U, V> Pair<U, V> makePair(U f, V s) { return new Pair<>(f, s); }
    }

    interface IntComparator {
        int compare(int a, int b);
    }
}
